const e="Ils ne sont pas nés de la pierre. Du moins, personne ne sait s'ils sont nés tout court.",t="Légende de Nordheim",n=["Peuple & Lignée","Peuple de la Pierre","Codex #PEU-011"],s=[11,12],a="Montagnes de Nordheim",i="Robustesse, Taillage de pierre, Longévité",o="130cm - 160cm",r="250",l="« Habitants des hautes pierres »",c="Morndal_icone.jpeg",u="Rare",d=[{title:"Présentation",type:"text",content:"Les Morndal sont un peuple ancien des montagnes de Nordheim. Leur corps massif et leur maîtrise de la roche les font souvent comparer aux nains des mythes du Vieux Monde."},{title:"Mythe d'Origine",type:"text",content:"Une légende tenace prétend que les Morndal ne naissent pas mais sont directement sculptés dans la roche avant d'être éveillés à la vie. Les Morndal n'ont jamais confirmé ce récit."},{title:"Relations régionales",type:"politique_list_long",content:[{headline:"Amical",title:"Les Skurf",content:"Partenariat pragmatique sur les routes de montagne et le commerce sous-terrain.",color:"#34D399"},{headline:"Commercial",title:"Barkovie & Glotergan",content:"Fournissent minerai, pierre et métaux ouvrés aux cités humaines de Nordheim.",color:"#34D399"}]},{title:"Aujourd'hui",type:"text",content:"Ils habitent de vastes cités sous la montagne à Nordheim et restent l'un des peuples les plus mystérieux d'Asun."}],m={citation:e,citation_author:t,tags:n,link_articles:s,class:"Ancienne / Montagnarde",repart:a,trait:i,height:o,age:r,surname:l,image:c,statut:u,sections:d};export{r as age,e as citation,t as citation_author,m as default,o as height,c as image,s as link_articles,a as repart,d as sections,u as statut,l as surname,n as tags,i as trait};
